export const getNamedGraphqlType = (type) => type.kind === 'named' ? type.name : getNamedGraphqlType(type.ofType);
export const resolveGraphqlOperation = (reference, target) => {
    if (target.kind !== 'query' && target.kind !== 'mutation')
        return undefined;
    let typeName = target.kind === 'query' ? reference.queryType : reference.mutationType;
    const path = [];
    for (const segment of target.name.split('.')) {
        const type = reference.types.find(({ name }) => name === typeName);
        if ((type === null || type === void 0 ? void 0 : type.kind) !== 'object' && (type === null || type === void 0 ? void 0 : type.kind) !== 'interface')
            return undefined;
        const field = type.fields.find(({ name }) => name === segment);
        if (!field)
            return undefined;
        path.push(field);
        typeName = getNamedGraphqlType(field.type);
    }
    const field = path.pop();
    if (!field)
        return undefined;
    return { field, parents: path };
};
